import { describe, test, expect, vi, beforeEach } from 'vitest';
import { renderHook } from '@testing-library/react';
import { createClient } from 'contentful';
import { getContentfulConfig, CONTENTFUL_PREVIEW_HOST, CONTENTFUL_DELIVERY_HOST } from '../config/contentful';
import { useContentfulClient } from './useContentfulClient';

vi.mock('contentful', () => ({
  createClient: vi.fn(),
}));

vi.mock('../config/contentful', async (importOriginal) => {
  const actual = await importOriginal<typeof import('../config/contentful')>();
  return {
    ...actual,
    getContentfulConfig: vi.fn(),
  };
});

const mockGetConfig = vi.mocked(getContentfulConfig);
const mockCreateClient = vi.mocked(createClient);

const BASE_CONFIG = {
  spaceId: 'space123',
  environment: 'master',
  accessToken: 'cda-token',
  previewAccessToken: 'cpa-token',
};

describe('useContentfulClient', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockCreateClient.mockReturnValue({} as ReturnType<typeof createClient>);
  });

  test('uses the Preview host + CPA token when preview is requested and a CPA token exists', () => {
    mockGetConfig.mockReturnValue(BASE_CONFIG);
    const { result } = renderHook(() => useContentfulClient({ preview: true }));

    expect(result.current.isPreview).toBe(true);
    expect(result.current.previewUnavailable).toBe(false);
    expect(result.current.client).not.toBeNull();
    expect(mockCreateClient).toHaveBeenCalledWith(
      expect.objectContaining({ accessToken: 'cpa-token', host: CONTENTFUL_PREVIEW_HOST }),
    );
  });

  test('flags previewUnavailable and does not enter preview mode when the CPA token is missing', () => {
    mockGetConfig.mockReturnValue({ ...BASE_CONFIG, previewAccessToken: '' });
    const { result } = renderHook(() => useContentfulClient({ preview: true }));

    expect(result.current.previewUnavailable).toBe(true);
    expect(result.current.isPreview).toBe(false);
  });

  test('uses the Delivery host + CDA token in normal (non-preview) mode', () => {
    mockGetConfig.mockReturnValue(BASE_CONFIG);
    const { result } = renderHook(() => useContentfulClient({ preview: false }));

    expect(result.current.isPreview).toBe(false);
    expect(result.current.previewUnavailable).toBe(false);
    expect(mockCreateClient).toHaveBeenCalledWith(
      expect.objectContaining({ accessToken: 'cda-token', host: CONTENTFUL_DELIVERY_HOST }),
    );
  });

  test('defaults to non-preview when called with no arguments', () => {
    mockGetConfig.mockReturnValue(BASE_CONFIG);
    const { result } = renderHook(() => useContentfulClient());

    expect(result.current.isPreview).toBe(false);
    expect(result.current.previewUnavailable).toBe(false);
  });

  test('returns a null client when required config (spaceId) is missing', () => {
    mockGetConfig.mockReturnValue({ ...BASE_CONFIG, spaceId: '' });
    const { result } = renderHook(() => useContentfulClient({ preview: true }));

    expect(result.current.client).toBeNull();
    expect(mockCreateClient).not.toHaveBeenCalled();
  });
});
